1	package stowage
2	
3	import (
4		"math"
5		"sort"
6		"strconv"
7		"strings"
8	)
9	
10	// Adjust 提交一次调整，可同时包含多件货物的装载、卸下和移动。
11	//
12	// 调整编号遵循编号规则（去掉首尾空白后非空）。成功后以相同编号和
13	// 相同内容重复提交，返回首次成功的结果而不再改变配载，即使之后另有
14	// 调整也一样；同一编号用于不同内容被拒绝。失败的调整不占用编号，
15	// 可以修正后重试。内容比较按编号去空白后的原始字节进行：登记处能
16	// 区分的编号（包括含无效 UTF-8 字节的编号）在内容判断中同样区分。
17	// 卸下操作忽略目标值，其目标不参与内容比较；装载与移动的目标舱位
18	// 参与比较。
19	//
20	// 一次调整中的所有操作作为一个整体生效：任一操作不合法，整次调整
21	// 都不生效，货物归属与各舱位重量保持原样。合法性按全部操作完成后的
22	// 最终配载判断：舱位总重量不得超过承重；同一目的地的货物可以共舱，
23	// 不同目的地共舱时所有货物都必须允许混装。重量合计超过 int64 可表示
24	// 范围也会被拒绝。
25	func (r *Registry) Adjust(adjustmentID string, ops []Op) (*AdjustmentResult, error) {
26		r.mu.Lock()
27		defer r.mu.Unlock()
28	
29		aid := strings.TrimSpace(adjustmentID)
30		if aid == "" {
31			return nil, fail(ErrInvalidID, "", "调整编号为空")
32		}
33	
34		// f 构造带调整编号的错误。
35		f := func(kind ErrorKind, id string, format string, args ...any) *Error {
36			e := fail(kind, id, format, args...)
37			e.AdjustmentID = aid
38			return e
39		}
40	
41		// 幂等：编号已成功使用过。
42		if saved, ok := r.adjustments[aid]; ok {
43			if r.contents[aid] == canonicalKey(ops) {
44				return cloneResult(saved), nil
45			}
46			return nil, f(ErrAdjustmentIDConflict, aid, "调整编号 %s 已用于不同内容", aid)
47		}
48	
49		if len(ops) == 0 {
50			return nil, f(ErrEmptyAdjustment, aid, "调整 %s 不包含任何操作", aid)
51		}
52	
53		vops, final, affected, err := r.prepareOps(ops, f)
54		if err != nil {
55			return nil, err
56		}
57	
58		// 按最终配载校验承重与混装限制，返回第一个问题即拒绝整次调整；
59		// 拒绝原因到结构化错误的转换与 AmendCargo 共用。
60		if rej := r.firstRejection(final); rej != nil {
61			return nil, rejectionError(rej, f)
62		}
63	
64		// 全部合法，正式生效。先计算受影响舱位调整前后的重量。
65		cargoChanges := make([]CargoChange, 0, len(vops))
66		compChanges := make([]CompartmentChange, 0, len(affected))
67		for id := range affected {
68			compChanges = append(compChanges, CompartmentChange{
69				CompartmentID: id,
70				WeightBefore:  sumSet(r.compartments[id].cargo),
71				WeightAfter:   sumSet(final[id]),
72			})
73		}
74		sort.Slice(compChanges, func(i, j int) bool {
75			return compChanges[i].CompartmentID < compChanges[j].CompartmentID
76		})
77	
78		for _, v := range vops {
79			c := v.cargo
80			from := c.compartmentID
81			var to string
82			switch v.op.Kind {
83			case OpLoad:
84				r.compartments[v.target.id].cargo[c.id] = c
85				c.compartmentID = v.target.id
86				to = v.target.id
87			case OpUnload:
88				delete(r.compartments[from].cargo, c.id)
89				c.compartmentID = ""
90			case OpMove:
91				delete(r.compartments[from].cargo, c.id)
92				r.compartments[v.target.id].cargo[c.id] = c
93				c.compartmentID = v.target.id
94				to = v.target.id
95			}
96			cargoChanges = append(cargoChanges, CargoChange{CargoID: c.id, From: from, To: to})
97		}
98		sort.Slice(cargoChanges, func(i, j int) bool {
99			return cargoChanges[i].CargoID < cargoChanges[j].CargoID
100		})
101	
102		result := &AdjustmentResult{
103			ID:                 aid,
104			CargoChanges:       cargoChanges,
105			CompartmentChanges: compChanges,
106		}
107		r.adjustments[aid] = result
108		r.contents[aid] = canonicalKey(ops)
109		return cloneResult(result), nil
110	}
111	
112	// validOp 是一条通过逐条校验的操作，附带其涉及的内部记录。
113	type validOp struct {
114		op     Op
115		cargo  *cargo
116		target *compartment // 装载/移动的目标舱位；卸下时为 nil
117	}
118	
119	// prepareOps 逐条校验操作并在模拟配载上应用全部操作。
120	// 调用方必须持有 r.mu。任一操作不合法时返回该错误，最终配载与受影响
121	// 舱位集合只在全部操作合法时返回。受影响舱位包括各操作的原舱位与
122	// 目标舱位（交换中的两个舱位都会纳入）。
123	func (r *Registry) prepareOps(
124		ops []Op,
125		failf func(kind ErrorKind, id string, format string, args ...any) *Error,
126	) (vops []validOp, final map[string]map[string]*cargo, affected map[string]bool, err error) {
127		seen := make(map[string]bool)
128		vops = make([]validOp, 0, len(ops))
129		affected = make(map[string]bool)
130	
131		for _, op := range ops {
132			cid := strings.TrimSpace(op.CargoID)
133			if cid == "" {
134				return nil, nil, nil, failf(ErrInvalidID, "", "货物编号为空")
135			}
136			c, ok := r.cargos[cid]
137			if !ok {
138				return nil, nil, nil, failf(ErrNotFound, cid, "货物 %s 不存在", cid)
139			}
140			if seen[cid] {
141				return nil, nil, nil, failf(ErrDuplicateOp, cid, "货物 %s 在同一次调整中出现多次", cid)
142			}
143			seen[cid] = true
144	
145			switch op.Kind {
146			case OpLoad:
147				if c.compartmentID != "" {
148					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 已装载于舱位 %s，不能再次装载", cid, c.compartmentID)
149				}
150				tid := strings.TrimSpace(op.Target)
151				if tid == "" {
152					return nil, nil, nil, failf(ErrInvalidID, "", "目标舱位编号为空")
153				}
154				t, ok := r.compartments[tid]
155				if !ok {
156					return nil, nil, nil, failf(ErrNotFound, tid, "舱位 %s 不存在", tid)
157				}
158				vops = append(vops, validOp{op, c, t})
159				affected[t.id] = true
160			case OpUnload:
161				if c.compartmentID == "" {
162					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 未装载，不能卸下", cid)
163				}
164				vops = append(vops, validOp{op, c, nil})
165				affected[c.compartmentID] = true
166			case OpMove:
167				if c.compartmentID == "" {
168					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 未装载，不能移动", cid)
169				}
170				tid := strings.TrimSpace(op.Target)
171				if tid == "" {
172					return nil, nil, nil, failf(ErrInvalidID, "", "目标舱位编号为空")
173				}
174				t, ok := r.compartments[tid]
175				if !ok {
176					return nil, nil, nil, failf(ErrNotFound, tid, "舱位 %s 不存在", tid)
177				}
178				if t.id == c.compartmentID {
179					return nil, nil, nil, failf(ErrDuplicateOp, cid, "货物 %s 已在舱位 %s，不能移动到原舱位", cid, t.id)
180				}
181				vops = append(vops, validOp{op, c, t})
182				affected[c.compartmentID] = true
183				affected[t.id] = true
184			default:
185				return nil, nil, nil, failf(ErrInvalidOp, cid, "货物 %s 的操作种类 %d 无法识别", cid, int(op.Kind))
186			}
187		}
188	
189		// 在模拟配载上应用全部操作，判断以完成后的最终状态为准。
190		final = make(map[string]map[string]*cargo, len(r.compartments))
191		for id, comp := range r.compartments {
192			set := make(map[string]*cargo, len(comp.cargo))
193			for cid, c := range comp.cargo {
194				set[cid] = c
195			}
196			final[id] = set
197		}
198		for _, v := range vops {
199			switch v.op.Kind {
200			case OpLoad:
201				final[v.target.id][v.cargo.id] = v.cargo
202			case OpUnload:
203				delete(final[v.cargo.compartmentID], v.cargo.id)
204			case OpMove:
205				delete(final[v.cargo.compartmentID], v.cargo.id)
206				final[v.target.id][v.cargo.id] = v.cargo
207			}
208		}
209		return vops, final, affected, nil
210	}
211	
212	// evaluateFinal 按最终配载评估每个舱位的承重与混装限制，一个舱位可以
213	// 同时得到重量原因（超重或溢出）与混装原因。结果不保证顺序。
214	// 调用方必须持有 r.mu。
215	func (r *Registry) evaluateFinal(final map[string]map[string]*cargo) []*Rejection {
216		var rejs []*Rejection
217		for id, set := range final {
218			comp := r.compartments[id]
219	
220			// 重量原因：溢出优先，溢出时不提供任何重量数值。
221			var sum int64
222			overflow := false
223			for _, c := range set {
224				if c.weight > math.MaxInt64-sum {
225					overflow = true
226					break
227				}
228				sum += c.weight
229			}
230			var rej *Rejection
231			if overflow {
232				rej = &Rejection{
233					CompartmentID: id,
234					Kind:          ErrOverflow,
235					MaxWeight:     comp.maxWeight,
236				}
237			} else if sum > comp.maxWeight {
238				rej = &Rejection{
239					CompartmentID:   id,
240					Kind:            ErrOverweight,
241					MaxWeight:       comp.maxWeight,
242					UsedWeight:      sum,
243					RemainingWeight: comp.maxWeight - sum,
244					Overweight:      sum - comp.maxWeight,
245				}
246			}
247	
248			// 混装原因：不同目的地共舱时，列出全部不允许混装的货物。
249			destinations := make(map[string][]string)
250			destSet := make(map[string]bool)
251			var offenders []string
252			for _, c := range set {
253				destinations[c.destination] = append(destinations[c.destination], c.id)
254				destSet[c.destination] = true
255				if !c.allowMixed {
256					offenders = append(offenders, c.id)
257				}
258			}
259			if len(destSet) > 1 && len(offenders) > 0 {
260				dests := make([]MixedDestination, 0, len(destinations))
261				for dest, ids := range destinations {
262					sorted := append([]string(nil), ids...)
263					sort.Strings(sorted)
264					dests = append(dests, MixedDestination{Destination: dest, CargoIDs: sorted})
265				}
266				sort.Slice(dests, func(i, j int) bool {
267					return dests[i].Destination < dests[j].Destination
268				})
269				sort.Strings(offenders)
270				mr := &Rejection{
271					CompartmentID:  id,
272					Kind:           ErrMixedLoading,
273					MaxWeight:      comp.maxWeight,
274					Destinations:   dests,
275					OffendingCargo: offenders,
276				}
277				if rej != nil {
278					rejs = append(rejs, rej, mr)
279				} else {
280					rejs = append(rejs, mr)
281				}
282			} else if rej != nil {
283				rejs = append(rejs, rej)
284			}
285		}
286		return rejs
287	}
288	
289	// firstRejection 以与正式调整一致的顺序返回第一个拒绝原因；没有则 nil。
290	// 调用方必须持有 r.mu。
291	func (r *Registry) firstRejection(final map[string]map[string]*cargo) *Rejection {
292		rejs := r.evaluateFinal(final)
293		if len(rejs) == 0 {
294			return nil
295		}
296		sort.Slice(rejs, func(i, j int) bool {
297			if rejs[i].CompartmentID != rejs[j].CompartmentID {
298				return rejs[i].CompartmentID < rejs[j].CompartmentID
299			}
300			return rejKindOrder(rejs[i].Kind) < rejKindOrder(rejs[j].Kind)
301		})
302		return rejs[0]
303	}
304	
305	// rejKindOrder 规定同一舱位的拒绝原因次序：重量（超重/溢出）先于混装。
306	func rejKindOrder(k ErrorKind) int {
307		switch k {
308		case ErrOverflow, ErrOverweight:
309			return 0
310		default:
311			return 1
312		}
313	}
314	
315	// firstOffender 返回混装原因中编号最小的货物，用于错误说明。
316	func (x *Rejection) firstOffender() string {
317		if len(x.OffendingCargo) == 0 {
318			return ""
319		}
320		return x.OffendingCargo[0]
321	}
322	
323	// canonicalKey 生成调整内容的规范化键：操作种类、货物、目标舱位相同
324	// 即视为相同内容，排列顺序不影响判断。卸下操作忽略目标舱位（执行时
325	// 同样忽略），其目标值不影响内容判断；装载与移动的目标舱位参与比较。
326	// 编号按去掉首尾空白后的原始字节精确比较：任何字节差异都视为不同内容，
327	// 包含无效 UTF-8 字节的编号与包含 Unicode 替代字符 U+FFFD 的编号也不相同。
328	func canonicalKey(ops []Op) string {
329		sorted := make([]Op, len(ops))
330		for i, op := range ops {
331			target := strings.TrimSpace(op.Target)
332			if op.Kind == OpUnload {
333				target = ""
334			}
335			sorted[i] = Op{
336				Kind:    op.Kind,
337				CargoID: strings.TrimSpace(op.CargoID),
338				Target:  target,
339			}
340		}
341		sort.Slice(sorted, func(i, j int) bool {
342			if sorted[i].Kind != sorted[j].Kind {
343				return sorted[i].Kind < sorted[j].Kind
344			}
345			if sorted[i].CargoID != sorted[j].CargoID {
346				return sorted[i].CargoID < sorted[j].CargoID
347			}
348			return sorted[i].Target < sorted[j].Target
349		})
350		// 长度前缀编码保留原始字节，不做任何字符集层面的规整，
351		// 任意字节内容都不会因分隔符或转义而碰撞。
352		var b strings.Builder
353		for _, op := range sorted {
354			b.WriteString(strconv.Itoa(int(op.Kind)))
355			b.WriteByte('|')
356			writeRawField(&b, op.CargoID)
357			writeRawField(&b, op.Target)
358		}
359		return b.String()
360	}
361	
362	// writeRawField 以“长度:原始字节”的形式写入一个字段。
363	func writeRawField(b *strings.Builder, s string) {
364		b.WriteString(strconv.Itoa(len(s)))
365		b.WriteByte(':')
366		b.WriteString(s)
367	}
368

